// Glass of water in a sunlit room — Image
// Wire iChannel0 = Buffer A. Tonemap + warm balance + vignette only.

vec3 aces(vec3 x){
  return clamp((x*(2.51*x+0.03))/(x*(2.43*x+0.59)+0.14), 0.0, 1.0);
}

void mainImage(out vec4 O, in vec2 U){
  vec2 q = U/iResolution.xy;
  vec3 col = texture(iChannel0, q).rgb;
  col *= vec3(.94, .800, 0.9);   // warm balance
  col = aces(col);
  col = pow(col, vec3(1.0/2.2));
  col *= 0.2 + 0.88*pow(16.0*q.x*q.y*(1.0-q.x)*(1.0-q.y), 0.50);
  O = vec4(col, 1.0);
}

// Blooming flower in a glass of water — Buffer A
// Wire iChannel0 = Buffer A (self-feedback).
// One jittered path-sample per frame, accumulated in HDR; tonemap lives in Image.
// Camera state (yaw/pitch/accum + last mouse) sits in two texels of the bottom
// row — drag to orbit, the view survives across frames.
// The flower opens by itself: ~30 s bloom, rest, close, repeat (68 s cycle).

// ---- cup parameters ----
#define CUP_R     0.100
#define CUP_H     0.600
#define CUP_WALL  0.013
#define CUP_WATER 0.9920
#define CUP_ROUGH 0.02
#define CAM_DIST  .175*iDate.y

const vec3 SUN0   = normalize(vec3(0.9, 0.185, 0.22)); // low evening light
const vec3 SUNCOL = vec3(1.38, 1.05, 0.68) * 4.2;
const vec3 GC     = vec3(0.0, 0.710, -0.22);           // glass base center
const vec3 WINC   = vec3(3.0, 1.7, 0.8);               // window center on +x wall
const vec2 WINR   = vec2(0.55, 0.45);                  // window half-size (y,z)
const vec3 FC     = vec3(0.0, 1.525, -0.22);           // flower head center
#define PI 3.14159265

vec3 gSun;    // per-frame jittered sun
float gBloom; // flower opening 0..1

float sdBox(vec3 p, vec3 b){ vec3 q=abs(p)-b; return length(max(q,0.))+min(max(q.x,max(q.y,q.z)),0.); }
float sdCyl(vec3 p, float r, float h){ vec2 d=vec2(length(p.xz)-r, abs(p.y)-h); return min(max(d.x,d.y),0.)+length(max(d,0.)); }
float hash(vec2 v){ return fract(sin(dot(v, vec2(127.1,311.7)))*43758.5453); }
mat2 rot2(float a){ float c=cos(a), s=sin(a); return mat2(c,-s,s,c); }

float bloomAt(float t){
  float ph = mod(t, 68.0);
  return smoothstep(3.0, 33.0, ph) * (1.0 - smoothstep(48.0, 64.0, ph));
}

float tableD(vec3 p){
  float top  = sdBox(p-vec3(0.,0.65,0.), vec3(0.62,0.035,0.46))-0.012;
  float leg  = sdCyl(p-vec3(0.,0.325,0.), 0.065, 0.325);
  float base = sdCyl(p-vec3(0.,0.035,0.), 0.27, 0.035)-0.01;
  return min(top, min(leg, base));
}

// ---------- flower ----------
float sdEll(vec3 p, vec3 r){
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

// petal in local frame: grows along +x from origin, thin in y, wide in z
float sdPetal(vec3 p, float L, float W, float bend, float cup){
  float x01 = clamp(p.x/L, 0.0, 1.0);
  p.y += bend * p.x*p.x;                    // curl along length
  p.y -= cup * p.z*p.z / W;                 // cup across width
  float w = 0.30 + 0.70*sin(PI*mix(0.18, 0.95, x01));  // width profile
  p.z /= w;
  p.z += 0.007*sin(x01*13.0);               // gentle wavy edge
  return sdEll(p - vec3(L*0.52, 0.0, 0.0), vec3(L*0.56, 0.010, W)) * min(w,1.0) * 0.60;
}

// (distance, material): 6 stem/receptacle, 7 petals, 8 stamens
vec2 flowerD(vec3 p){
  // stem: bows out a little and returns under the head
  vec3 sp = p;
  sp.x -= GC.x + 0.030*sin((p.y-0.755)*4.1);
  sp.z -= GC.z;
  vec2 res = vec2(sdCyl(sp - vec3(0.0, 1.135, 0.0), 0.012, 0.40), 6.0);

  vec3 q = p - FC;
  float rr = length(q);
  // conservative bound: outside the head sphere the petals are at least
  // (rr - 0.45) away — never overestimate, or petals get clipped
  if(rr > 0.50) return vec2(min(res.x, rr - 0.45), 6.0);

  // three petal layers, outer opens first
  for(int l=0; l<3; l++){
    float fl = float(l);
    float n = 8.0;                                  // same count per layer:
    float sector = 6.2831853/n;                     // a regular rosette
    float twist = fl*sector*0.5;                    // each layer covers the gaps
    float a = atan(q.z, q.x) + twist;
    float i0 = floor(a/sector + 0.5);
    float bl = smoothstep(0.20*fl, 0.55 + 0.22*fl, gBloom);
    float open = mix(0.10, 0.98 - 0.24*fl, bl);     // opens into a bowl, not flat
    float L = 0.225 - 0.030*fl, W = 0.088 - 0.012*fl;
    float bend = mix(2.4, -0.5, bl);                // wrap inward -> tips curl back
    float cup  = mix(0.55, 0.40, bl);
    // check the neighbours too: twisted petals cross sector borders
    for(int o=-1; o<=1; o++){
      float ai = (i0 + float(o))*sector - twist;
      vec3 v = q;
      v.xz = rot2(-ai) * v.xz;
      v.y -= 0.012*fl;
      v.xy = rot2(PI*0.5 - open) * v.xy;            // closed: petal points up
      v.x -= 0.030;
      float d = sdPetal(v, L, W, bend, cup);
      if(d < res.x) res = vec2(d, 7.0);
    }
  }

  // receptacle: green cup that seals the base of the bud
  float rec = length(q - vec3(0.0, -0.006, 0.0)) - 0.034;
  if(rec < res.x) res = vec2(rec, 6.0);

  // stamens: ring of anthers + pistil, tucked away until the flower opens
  float reveal = smoothstep(0.50, 0.85, gBloom);
  float a2 = atan(q.z, q.x);
  float ai2 = floor(a2/(6.2831853/12.0) + 0.5)*(6.2831853/12.0);
  vec3 st = q; st.xz = rot2(-ai2)*st.xz;
  float anth = length(st - vec3(0.045, 0.035 + 0.014*sin(ai2*7.0), 0.0)) - 0.009;
  float pist = length(q - vec3(0.0, 0.022, 0.0)) - 0.024;
  float stam = min(anth, pist) + (1.0-reveal)*0.05;
  if(stam < res.x) res = vec2(stam, 8.0);

  return res;
}

// ---------- opaque scene ----------
vec2 opq(vec3 p){
  float d = -sdBox(p-vec3(0.,1.5,0.5), vec3(3.0,1.5,3.5));
  d = max(d, -sdBox(p-WINC, vec3(0.35, WINR.x, WINR.y)));
  vec2 res = vec2(d, 1.0);
  float bars = min(
    sdBox(p-WINC, vec3(0.06, WINR.x, 0.035)),
    sdBox(p-WINC, vec3(0.06, 0.035, WINR.y)));
  bars = min(bars, max(sdBox(p-WINC, vec3(0.07, WINR.x+0.06, WINR.y+0.06)),
                      -sdBox(p-WINC, vec3(0.20, WINR.x, WINR.y))));
  if(bars<res.x) res=vec2(bars, 3.0);
  float dT = tableD(p);
  if(dT<res.x) res=vec2(dT, 2.0);
  vec2 fd = flowerD(p);
  if(fd.x<res.x) res=fd;
  return res;
}

// ---------- glass ----------
float glassD(vec3 p){
  vec3 q = p-GC;
  float hh = CUP_H*0.5;
  float outer = sdCyl(q-vec3(0.,hh,0.), CUP_R, hh)-0.008;
  float inner = sdCyl(q-vec3(0., 0.05+(CUP_H+0.10)*0.5, 0.), CUP_R-CUP_WALL, (CUP_H+0.10)*0.5);
  return max(outer, -inner);
}

// ---------- water inside the glass ----------
float waterD(vec3 p){
  vec3 q = p-GC;
  float wl = 0.05 + CUP_WATER*(CUP_H-0.10);
  return sdCyl(q-vec3(0.,(0.05+wl)*0.5,0.), CUP_R-CUP_WALL+0.001, max((wl-0.05)*0.5, 0.001));
}
vec3 waterN(vec3 p){
  vec2 e = vec2(0.0012, -0.0012);
  return normalize( e.xyy*waterD(p+e.xyy) + e.yyx*waterD(p+e.yyx)
                  + e.yxy*waterD(p+e.yxy) + e.xxx*waterD(p+e.xxx) );
}

vec2 map(vec3 p){
  vec2 r = opq(p);
  float g = glassD(p);
  if(g<r.x) r = vec2(g, 4.0);
  float w = waterD(p);
  if(w<r.x) r = vec2(w, 5.0);
  return r;
}

vec3 normalAt(vec3 p){
  vec2 e = vec2(0.0012, -0.0012);
  return normalize( e.xyy*map(p+e.xyy).x + e.yyx*map(p+e.yyx).x
                  + e.yxy*map(p+e.yxy).x + e.xxx*map(p+e.xxx).x );
}

vec2 march(vec3 ro, vec3 rd, bool withGlass){
  float t = 0.0; float m = -1.0;
  for(int i=0;i<128;i++){
    vec3 p = ro + rd*t;
    vec2 h = withGlass ? map(p) : opq(p);
    if(h.x<0.001){ m=h.y; break; }
    t += h.x;
    if(t>25.0) break;
  }
  return vec2(t, m);
}

// geometric sun visibility through the window
float sunVis(vec3 p){
  float t = (3.0-p.x)/gSun.x;
  if(t<0.0) return 0.0;
  vec3 h = p + gSun*t;
  vec2 d = abs(vec2(h.y-WINC.y, h.z-WINC.z)) - WINR;
  if(max(d.x,d.y)>0.0) return 0.0;
  if(abs(h.z-WINC.z)<0.045 || abs(h.y-WINC.y)<0.045) return 0.0;
  return 1.0;
}

// translucent shadow cast by the glass, the water and the flower
float glassShadow(vec3 ro, vec3 rd){
  float rG = 1.0, rW = 1.0, rF = 1.0, t = 0.02;
  for(int i=0;i<28;i++){
    vec3 p = ro + rd*t;
    float hg = glassD(p), hw = waterD(p), hf = flowerD(p).x;
    rG = min(rG, 18.0*hg/t);
    rW = min(rW, 18.0*hw/t);
    rF = min(rF, 14.0*hf/t);
    t += clamp(min(hf, min(hg,hw)), 0.012, 0.12);
    if(t>1.8) break;
  }
  rG = clamp(rG, 0.0, 1.0); rW = clamp(rW, 0.0, 1.0); rF = clamp(rF, 0.0, 1.0);
  // glass dims a little, the water column more, petals almost fully
  return (0.40 + 0.60*rG) * (0.22 + 0.78*rW) * (0.12 + 0.88*rF);
}

// self-shadowing from the table only; window/frame occlusion is in sunVis
float softShadow(vec3 ro, vec3 rd){
  float res=1.0, t=0.02;
  for(int i=0;i<32;i++){
    float h = tableD(ro+rd*t);
    res = min(res, 14.0*h/t);
    t += clamp(h, 0.02, 0.3);
    if(res<0.005 || t>4.0) break;
  }
  return clamp(res, 0.0, 1.0);
}

float ao(vec3 p, vec3 n){
  float o=0.0, s=1.0;
  for(int i=1;i<=5;i++){
    float h=0.03*float(i);
    o += (h - map(p+n*h).x)*s;
    s *= 0.7;
  }
  return clamp(1.0-2.5*o, 0.0, 1.0);
}

vec3 sky(vec3 rd){
  vec3 c = mix(vec3(0.60,0.74,0.95), vec3(1.00,1.00,1.05), clamp(rd.y*2.+0.4,0.,1.))*3.0;
  float s = max(dot(rd,gSun),0.0);
  c += SUNCOL*(pow(s,900.0)*40.0 + pow(s,16.0)*0.35);
  return c;
}

// fake caustic from the glass
float caustic(vec3 p){
  vec3 L = -gSun;
  float focusY = GC.y + 0.10;
  float tt = (focusY - p.y)/(-L.y);
  if(tt<0.0) return 0.0;
  vec2 cc = GC.xz + L.xz*tt;
  float c = length(p.xz - cc);
  float ring = exp(-pow((c-CUP_R*0.45)*30.0, 2.0))*2.2;
  float spot = exp(-pow(c*16.0, 2.0))*1.5;
  return ring + spot;
}

vec3 shade(vec3 p, vec3 n, float m, vec3 rd){
  vec3 alb;
  if(m==1.0){
    if(p.y<0.01 && n.y>0.5){          // floor boards
      float b = floor(p.x*2.2);
      float f = fract(p.x*2.2);
      alb = mix(vec3(0.46,0.31,0.20), vec3(0.56,0.40,0.27), fract(sin(b*17.7)*43758.5));
      alb *= 0.86 + 0.14*smoothstep(0.0,0.05,f)*smoothstep(1.0,0.95,f);
    } else if(p.y>2.98){              // ceiling
      alb = vec3(0.84,0.82,0.79);
    } else {                          // walls
      alb = vec3(0.82,0.74,0.62);
    }
  } else if(m==2.0){                  // table wood
    float grain = 0.88 + 0.12*sin(p.x*18.0 + sin(p.z*11.0)*2.0);
    alb = vec3(0.36,0.20,0.115)*grain;
  } else if(m==3.0){                  // frame, painted
    alb = vec3(0.88,0.86,0.83);
  } else if(m==6.0){                  // stem
    alb = vec3(0.14,0.34,0.11) * (0.85+0.15*sin(p.y*60.0));
  } else if(m==7.0){                  // petal: white core -> pink tip
    vec3 lp = p - FC;
    float rt = clamp(length(lp)/0.24, 0.0, 1.0);
    alb = mix(vec3(0.99,0.93,0.91), vec3(0.93,0.32,0.52), pow(rt,1.6));
    float ang = atan(lp.z,lp.x);
    alb *= 0.93 + 0.07*sin(ang*36.0 + rt*20.0);   // faint veins
  } else if(m==8.0){                  // stamens
    alb = vec3(0.95,0.72,0.18) * (0.8+0.2*hash(floor(p.xz*300.0)));
  } else {
    alb = vec3(0.5);
  }

  float sv  = sunVis(p);
  float sh  = sv>0.0 ? softShadow(p+n*0.01, gSun) : 0.0;
  float gsh = sv>0.0 ? glassShadow(p+n*0.01, gSun) : 1.0;
  float dif = max(dot(n,gSun), 0.0);
  float occ = ao(p, n);

  vec3 col = alb * SUNCOL * dif * sv * sh * gsh;

  // petal translucency: sun shining through the thin petal
  if(m==7.0){
    float back = max(dot(gSun, -n), 0.0);
    col += vec3(1.15,0.42,0.58) * SUNCOL * pow(back, 2.0) * 0.50 * sv;
    col += alb * SUNCOL * 0.16 * sv;
    col += alb * vec3(0.55,0.63,0.80) * 0.30;     // petals catch a lot of skylight
  }
  if(m==8.0){ // waxy stamen highlight + skylight fill inside the bowl
    vec3 hv = normalize(gSun - normalize(p-FC));
    col += SUNCOL * pow(max(dot(n,hv),0.0), 40.0) * 0.35 * sv;
    col += alb * vec3(0.55,0.63,0.80) * 0.25;
  }

  if(m==2.0 || (m==1.0 && p.y<0.01)){
    col += alb * SUNCOL * caustic(p) * sv * sh;
    float contact = length(p.xz-GC.xz);
    col *= 1.0 - 0.4*(1.0-smoothstep(CUP_R*0.85, CUP_R*1.8, contact))*step(abs(p.y-GC.y), 0.08);
  }

  // window as an area light: falls off with distance, cosine-weighted,
  // partially blocked by the glass
  vec3 toW = WINC - p;
  float dw = length(toW); toW /= dw;
  float solid = 1.8/(1.0 + dw*dw*0.30);
  float ndw = max(dot(n,toW), 0.0)*0.85 + 0.15;
  col += alb * vec3(0.55,0.63,0.80) * 0.34 * solid * ndw * occ * (0.55+0.45*gsh);
  // warm bounce off the sun patch on the floor
  vec3 toF = normalize(vec3(-1.2,0.0,0.3) - p);
  col += alb * vec3(0.50,0.33,0.18) * 0.14 * (max(dot(n,toF),0.0)*0.6+0.4) * occ;
  col += alb * vec3(0.028,0.027,0.026) * occ;   // faint multi-bounce floor

  return col;
}

vec3 renderOpaque(vec3 ro, vec3 rd){
  vec2 h = march(ro, rd, false);
  if(h.y<0.0) return sky(rd);
  vec3 p = ro + rd*h.x;
  vec2 e = vec2(0.0012,-0.0012);
  vec3 n = normalize( e.xyy*opq(p+e.xyy).x + e.yyx*opq(p+e.yyx).x
                    + e.yxy*opq(p+e.yxy).x + e.xxx*opq(p+e.xxx).x );
  return shade(p, n, h.y, rd);
}

// ---------- volumetric sun shafts ----------
vec3 volumetric(vec3 ro, vec3 rd, float tmax, float jit){
  float stp = min(tmax, 8.0)/40.0;
  vec3 acc = vec3(0.0);
  for(int i=0;i<40;i++){
    // independent jitter per step kills banding
    float t = (float(i) + fract((jit + float(i))*1.618034)) * stp;
    if(t>tmax) break;
    vec3 p = ro + rd*t;
    acc += SUNCOL * sunVis(p) * stp;
  }
  float fwd = pow(max(dot(rd, gSun)*0.5+0.5, 0.0), 3.0);
  return acc * 0.042 * (0.22 + 1.15*fwd);
}

void mainImage(out vec4 O, in vec2 U){
  ivec2 iu = ivec2(U);
  gBloom = bloomAt(iTime);

  // ---- camera state from the buffer ----
  vec4 stt = texelFetch(iChannel0, ivec2(0,0), 0); // yaw, pitch, accum, magic
  vec4 ms  = texelFetch(iChannel0, ivec2(1,0), 0); // last mouse xy, wasDown, magic
  float yaw = stt.x, pitch = stt.y, acc = stt.z;
  if(iFrame == 0 || stt.w != 123.0){ yaw = 4.503; pitch = 0.; acc = 10.0; }

  bool down = iMouse.z > 0.0;
  bool wasDown = ms.z > 0.5;
  if(down && wasDown){
    vec2 d = iMouse.xy - ms.xy;
    if(abs(d.x) + abs(d.y) > 0.5){
      yaw   += d.x * 0.006;
      pitch -= d.y * 0.006;               // iMouse y grows upward
      pitch  = clamp(pitch, -0.02, 0.70);
      acc    = min(acc, 12.0);            // soft restart on drag
    }
  }
  // while the flower is moving, keep a rolling 28-frame window:
  // petals travel less than a pixel per frame, accumulation wins over ghosting
  if(abs(bloomAt(iTime) - bloomAt(iTime - iTimeDelta)) > 1e-5) acc = min(acc, 28.0);
  acc += 1.0;

  // state texels live in the bottom-left corner
  if(iu.y == 0 && iu.x < 2){
    O = (iu.x == 0) ? vec4(yaw, pitch, acc, 123.0)
                    : vec4(iMouse.xy, down ? 1.0 : 0.0, 123.0);
    return;
  }

  // ---- one path sample ----
  vec2 frag = U;
  // wrap the seed: an ever-growing iFrame pushes hash() arguments into the
  // range where float32 sin() quantizes and the dither collapses into bands
  float seed = mod(float(iFrame), 256.0);
  vec2 jit = vec2(hash(frag + seed*vec2(17.13, 5.71)),
                  hash(frag + seed*vec2(3.77, 29.17))) - 0.5;

  // per-pixel AND per-frame sun jitter: penumbra dithers spatially instead of
  // banding into discrete shadow copies while the accumulation window is short
  gSun = normalize(SUN0 + 0.024*(vec3(hash(frag + seed*vec2(1.7,9.3)),
                                      hash(frag + seed*vec2(6.1,3.7)),
                                      hash(frag + seed*vec2(2.9,8.3))) - 0.5));

  vec2 uv = (2.0*(frag + jit) - iResolution.xy)/iResolution.y;

  float taY = mix(1.49, 1.08, smoothstep(0.55, 2.2, CAM_DIST));
  vec3 ta = vec3(0.0, taY-0.2, -0.20);
  vec3 ro = ta + CAM_DIST*vec3(sin(yaw)*cos(pitch), sin(pitch), cos(yaw)*cos(pitch));
  vec3 fw = normalize(ta-ro);
  vec3 rt = normalize(cross(fw, vec3(0,1,0)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(fw*1.65 + rt*uv.x + up*uv.y);

  vec2 h = march(ro, rd, true);
  vec3 col;
  float tmax = h.y>0.0 ? h.x : 25.0;

  if(h.y<0.0){
    col = sky(rd);
  } else if(h.y==4.0){
    // ---- glass ----
    vec3 p = ro + rd*h.x;
    vec3 n = normalAt(p);
    float F = 0.04 + 0.96*pow(clamp(1.0+dot(rd,n),0.0,1.0), 5.0);
    vec3 rr = reflect(rd, n);
    vec3 rj = vec3(hash(frag+seed*vec2(1.3,7.1)),
                   hash(frag+seed*vec2(5.2,3.3)),
                   hash(frag+seed*vec2(9.1,2.7))) - 0.5;
    rr = normalize(rr + CUP_ROUGH*3.0*rj);
    if(dot(rr,n)<0.0) rr = reflect(rr, n);
    vec3 refl = renderOpaque(p+n*0.01, rr);
    float tw = (3.0-p.x)/rr.x;
    if(tw>0.0){
      vec3 hw = p + rr*tw;
      vec2 dw = abs(vec2(hw.y-WINC.y, hw.z-WINC.z)) - WINR;
      if(max(dw.x,dw.y)<0.0) refl += vec3(1.2,1.12,0.95)*1.2;
    }
    refl += SUNCOL * pow(max(dot(rr,gSun),0.0), 700.0) * 30.0 * sunVis(p);
    vec3 rf = refract(rd, n, 1.0/1.5);
    if(dot(rf,rf)<0.001) rf = rr;
    vec3 rj2 = vec3(hash(frag+seed*vec2(2.7,11.3)),
                    hash(frag+seed*vec2(8.9,4.1)),
                    hash(frag+seed*vec2(3.1,6.7))) - 0.5;
    rf = normalize(rf + CUP_ROUGH*2.0*rj2);
    // does the refracted ray enter the water?
    vec3 trans;
    float twt = 0.015; bool hitW = false; vec3 pw = p;
    for(int i=0;i<32;i++){
      pw = p + rf*twt;
      float dw = waterD(pw);
      if(dw<0.001){ hitW = true; break; }
      twt += max(dw, 0.004);
      if(twt>0.8) break;
    }
    if(hitW){
      vec3 nw = waterN(pw);
      vec3 rf2 = refract(rf, nw, 1.0/1.33);
      if(dot(rf2,rf2)<0.001) rf2 = rf;
      trans = renderOpaque(pw + rf2*0.03, rf2) * vec3(0.78,0.92,0.97);
      trans += SUNCOL * pow(max(dot(reflect(rf,nw),gSun),0.0), 400.0) * 8.0 * sunVis(pw);
    } else {
      trans = renderOpaque(p + rf*0.02, rf);
    }
    float gr = pow(1.0-abs(dot(rd,n)), 2.0);
    trans *= mix(vec3(0.97,1.0,0.985), vec3(0.42,0.62,0.55), gr);
    col = mix(trans, refl, F);
    col += vec3(1.0,0.95,0.85)*pow(F,2.0)*0.15*sunVis(p);
  } else if(h.y==5.0){
    // ---- water surface hit directly ----
    vec3 p = ro + rd*h.x;
    vec3 n = waterN(p);
    float F = 0.02 + 0.98*pow(clamp(1.0+dot(rd,n),0.0,1.0), 5.0);
    vec3 rr = reflect(rd, n);
    vec3 refl = renderOpaque(p+n*0.01, rr);
    refl += SUNCOL * pow(max(dot(rr,gSun),0.0), 600.0) * 20.0 * sunVis(p);
    vec3 rf = refract(rd, n, 1.0/1.33);
    if(dot(rf,rf)<0.001) rf = rr;
    vec3 trans = renderOpaque(p + rf*0.05, rf) * vec3(0.80,0.93,0.97);
    col = mix(trans, refl, F);
  } else {
    vec3 p = ro + rd*h.x;
    vec3 n = normalAt(p);
    col = shade(p, n, h.y, rd);
  }

  col += volumetric(ro, rd, tmax, hash(frag+seed*vec2(7.31,13.7)));

  // ---- temporal accumulation (linear HDR) ----
  vec3 prev = texelFetch(iChannel0, iu, 0).rgb;
  float k = 1.0/min(acc, 400.0);
  O = vec4(mix(prev, col, k), 1.0);
}
